tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
git diff --quiet HEAD -- data tests/test_reveal_prerequisites.py storygame/story_package/obligations.py packages || { echo "WHY: data/, packages/, obligations.py or test_reveal_prerequisites.py was edited"; git diff --stat HEAD -- data tests/test_reveal_prerequisites.py storygame/story_package/obligations.py packages; exit 1; }
[ -f tests/test_delivery_variants.py ] || { echo "WHY: tests/test_delivery_variants.py missing"; exit 1; }
N=$($PY -m pytest --collect-only -q -p no:cacheprovider tests/test_delivery_variants.py 2>/dev/null | grep -c '::')
[ "$N" -ge 10 ] || { echo "WHY: only $N tests collected in test_delivery_variants.py; the spec lists cases a-i (need >= 10 test cases)"; exit 1; }
grep -rIl -i -E "kristin|brandon|rebecca|continuity" storygame/runtime/knowledge.py storygame/runtime/delivery_text.py 2>/dev/null && { echo "WHY: story names leaked into engine code"; exit 1; }
grep -q "delivery_variants" docs/markdown-story-authoring/knowledge-and-disclosure.md || { echo "WHY: docs not updated"; exit 1; }
grep -q "delivery_variants" storygame/story_package/models.py || { echo "WHY: model field missing"; exit 1; }
$PY - <<'EOF' || exit 1
# independent behavioural probe, not the worker's tests: base is used when no variant exists
from pathlib import Path
from storygame.story_package.loader import load_story_package
p = load_story_package(Path("data/stories/continuity-initiative"))
assert all(not getattr(k, "delivery_variants", ()) for k in p.knowledge.knowledge), "WHY: real package must not gain variants in this task"
dumped = p.knowledge.knowledge[0].model_dump(mode="json")
assert "delivery_variants" not in dumped, "WHY: empty delivery_variants must be excluded from serialization"
print("probe ok")
EOF
$PY -m pytest -q -p no:cacheprovider tests/test_delivery_variants.py tests/test_reveal_prerequisites.py tests/test_entry_variants.py tests/test_markdown_story_package.py tests/test_knowledge_projection.py tests/test_candidate_matcher.py tests/test_cloudflare_transport.py tests/test_knowledge_leakage_matrix.py tests/test_spine_expected_reveals.py tests/test_save_restore*.py 2>&1 | tail -25
[ "${PIPESTATUS[0]}" = 0 ] || { echo "WHY: focused suites failed"; exit 1; }
$PY -m ruff format --check . && $PY -m ruff check . || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A && git diff --cached > $OUT/e1.patch && wc -l $OUT/e1.patch && git diff --cached --stat | tail -15
